#!/usr/bin/env python3

import smbus2
import time
import logging
import signal
import sys

# Constants
ADS1115_ADDRESS = 0x48  # I2C address of the ADS1115
ADS1115_ADDR_GND = 0x00  # ADS1115 address for GND reference
ADS1115_ADDR_AIN0 = 0x01  # ADS1115 address for AIN0
ADS1115_ADDR_AIN1 = 0x02  # ADS1115 address for AIN1
ADS1115_ADDR_AIN2 = 0x03  # ADS1115 address for AIN2
ADS1115_ADDR_AIN3 = 0x04  # ADS1115 address for AIN3
ADS1115_PGA_GAIN = +/-4.096  # PGA gain setting
ADS1115_SPS_RATE = 128  # Sampling rate setting
ADS1115_DITH_SINGLE = 0x00  # Single-ended mode
ADS1115_DITH_DIFF = 0x01  # Differential mode
ADS1115_DITH_COMPLETE = 0x02  # Completed conversion
ADS1115_MODE_SINGLE_SHOT = 0x00  # Single-shot mode
ADS1115_MODE_CONTINUOUS = 0x01  # Continuous mode

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global variables
i2c_bus = None
bus_error = False

def initialize_i2c():
    """Initializes the I2C bus and handles potential errors."""
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(1)  # Use I2C bus 1
        logger.info("I2C bus initialized successfully.")
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus: {e}")
        raise

def read_adc_channel(channel):
    """Reads the specified ADC channel and returns the value as a 16-bit integer."""
    try:
        if channel == ADS1115_ADDR_GND:
            return i2c_bus.read_word_data(ADS1115_ADDRESS, channel)
        elif channel == ADS1115_ADDR_AIN0:
            return i2c_bus.read_word_data(ADS1115_ADDRESS, channel)
        elif channel == ADS1115_ADDR_AIN1:
            return i2c_bus.read_word_data(ADS1115_ADDRESS, channel)
        elif channel == ADS1115_ADDR_AIN2:
            return i2c_bus.read_word_data(ADS1115_ADDRESS, channel)
        elif channel == ADS1115_ADDR_AIN3:
            return i2c_bus.read_word_data(ADS1115_ADDRESS, channel)
        else:
            raise ValueError(f"Invalid ADC channel: {channel}")
    except Exception as e:
        logger.error(f"Error reading ADC channel {channel}: {e}")
        raise

def convert_to_signed_16bit(value):
    """Converts a 16-bit unsigned value to a signed 16-bit integer."""
    if value > 32767:
        return -((65535 - value) + 1)
    return value

def convert_to_unsigned_16bit(value):
    """Converts a signed 16-bit integer to a 16-bit unsigned integer."""
    if value < -32768:
        return (65535 - value) + 1
    return value

def read_adc_data(channel):
    """Reads the ADC data for the specified channel and returns a tuple of (value, status)."""
    try:
        value = convert_to_signed_16bit(read_adc_channel(channel))
        status = i2c_bus.read_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_OS_BIT)
        if status & ADS1115_OS_BIT_ERROR:
            raise IOError(f"I2C communication error: {status}")
        if status & ADS1115_OS_BIT_COMPLETE:
            return (value, status)
        else:
            return (value, None)
    except IOError as e:
        logger.error(f"I2C communication error: {e}")
        raise
    except Exception as e:
        logger.error(f"Error reading ADC data for channel {channel}: {e}")
        raise

def main():
    """Main function to read and print ADC data."""
    global i2c_bus
    try:
        initialize_i2c()
        i2c_bus.set_address(ADS1115_ADDRESS)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_OS_BIT, ADS1115_MODE_CONTINUOUS)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_PGA_BIT, ADS1115_PGA_GAIN)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_DITH_BIT, ADS1115_DITH_SINGLE)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_LAT_BIT, 0)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_DATA_BIT, 0)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_SINGLE_SHOT_BIT, 0)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_SINGLE_SHOT_BIT, 0)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_OS_BIT, ADS1115_MODE_COMPLETE)
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_ADDR_OS_BIT, 0)

        channel_list = [ADS1115_ADDR_AIN0, ADS1115_ADDR_AIN1, ADS1115_ADDR_AIN2, ADS1115_ADDR_AIN3]
        adc_readings = []

        while True:
            try:
                for channel in channel_list:
                    value, status = read_adc_data(channel)
                    if status is not None:
                        adc_readings.append((value, status))
                        print(f"Channel {channel}: {value}")
                        time.sleep(0.05)  # Adjust delay as needed
                time.sleep(0.1)  # Adjust scan rate as needed
            except KeyboardInterrupt:
                logger.info("Exiting program.")
                break
            except Exception as e:
                logger.error(f"An unexpected error occurred: {e}")
                break

    except Exception as e:
        logger.error(f"Initialization error: {e}")
        sys.exit(1)
    finally:
        if i2c_bus:
            try:
                i2c_bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
        logger.info("Program finished.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal.SIG_DFL)  # Handle Ctrl+C
    main()

