    global database_connection
    try:
        cursor = database_connection.cursor()
        cursor.execute("SELECT timestamp, temperature, humidity, pressure FROM readings ORDER BY timestamp DESC LIMIT 1")
        result = cursor.fetchone()
        if result:
            timestamp, temperature, humidity, pressure = result
            return timestamp, temperature, humidity, pressure
        else:
            logging.warning("No data found in the database.")
            return None, None, None, None
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
        return None, None, None, None
    except Exception as e:
        logging.error(f"Error reading database: {e}")
        return None, None, None, None

