import cv2
import numpy as np
from picamera2 import Picamera2, PreviewConfiguration
import signal
import sys

# Global flag to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGTERM signals for graceful shutdown."""
    global running
    running = False

def initialize_camera(camera_num):
    """Initializes a Picamera2 instance for a given camera number."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'RGB888', "size": (640, 480)})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera {camera_num}: {e}")
        return None

def capture_frames(picam2, camera_num):
    """Captures frames from a given camera and returns them as a numpy array."""
    try:
        frame = picam2.capture_array()
        return frame
    except Exception as e:
        print(f"Error capturing frame from camera {camera_num}: {e}")
        return None

def combine_frames(frame1, frame2):
    """Combines two frames side by side using numpy's np.hstack."""
    if frame1 is None or frame2 is None:
        return None
    return np.hstack((frame1, frame2))

def display_frame(frame, window_title):
    """Displays a combined frame in an OpenCV window."""
    cv2.imshow(window_title, frame)
    cv2.waitKey(30)

def main():
    """Main function to initialize and run the CSI camera capture."""
    global running
    picam2_0 = initialize_camera(0)
    picam2_1 = initialize_camera(1)

    if picam2_0 is None or picam2_1 is None:
        print("Failed to initialize one or more cameras. Exiting.")
        sys.exit(1)

    cv2.namedWindow('Dual CSI Cameras', cv2.WINDOW_NORMAL)

    try:
        while running:
            frame1 = capture_frames(picam2_0, 0)
            if frame1 is None:
                continue

            frame2 = capture_frames(picam2_1, 1)
            if frame2 is None:
                continue

            combined_frame = combine_frames(frame1, frame2)
            if combined_frame is None:
                continue

            display_frame(combined_frame, 'Dual CSI Cameras')

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if picam2_0:
            picam2_0.stop()
        if picam2_1:
            picam2_1.stop()
        cv2.destroyAllWindows()
        print("Camera resources released.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

