import picamera2
import pyzbar.pyzbar as pyzbar
import cv2
import numpy as np

def initialize_camera(resolution=(640, 480)):
    """Initializes the CSI camera with the specified resolution."""
    try:
        camera = picamera2.Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": resolution}))
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes any QR codes present in the frame."""
    try:
        decoded_objects = pyzbar.decode(frame)
        if decoded_objects:
            return decoded_objects[0].data.decode('utf-8')
        return None
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return None

def process_frame(camera, qr_code_data):
    """Processes a single frame to detect and display a QR code."""
    if qr_code_data:
        print('Hello, World!')
    else:
        print('No QR code detected.')

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        while True:
            frame = capture_frame(camera)
            if frame is None:
                continue

            qr_code_data = decode_qr_code(frame)

            if qr_code_data:
                process_frame(camera, qr_code_data)

            cv2.imshow('QR Code Scanner', frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        camera.stop()
        camera.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

