#!/usr/bin/env python3

"""
This program continuously monitors three digital input pins and drives two digital output pins
based on the state of those inputs. It uses the gpiozero library for clean and readable code.
"""

import time
import signal
import sys
import RPi.GPIO as GPIO

# Define GPIO pins using BCM numbering
BUTTON_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]

# Global variable to track the state of the output pins
output_state = {'on': False, 'off': False}

def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGINT signals for graceful exit."""
    print("\nExiting gracefully...")
    GPIO.cleanup()
    sys.exit(0)

def initialize_gpio():
    """Initializes the GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in BUTTON_PINS + OUTPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)  # Enable pull-up resistors
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def poll_buttons():
    """Polls the button pins and updates the output pins."""
    try:
        while True:
            for pin in BUTTON_PINS:
                if GPIO.input(pin) == GPIO.LOW:
                    if output_state['on']:
                        GPIO.output(OUTPUT_PINS[0], GPIO.LOW)
                        output_state['on'] = False
                    else:
                        GPIO.output(OUTPUT_PINS[1], GPIO.HIGH)
                        output_state['on'] = True
            time.sleep(0.05)
    except Exception as e:
        print(f"Error during button polling: {e}")
        GPIO.cleanup()
        sys.exit(1)

def toggle_output(pin):
    """Toggles the state of the specified output pin."""
    global output_state
    if pin not in output_state:
        print(f"Invalid output pin: {pin}")
        return

    if output_state['on']:
        GPIO.output(pin, GPIO.LOW)
        output_state['on'] = False
    else:
        GPIO.output(pin, GPIO.HIGH)
        output_state['on'] = True

def main():
    """Main function to run the program."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    print("Starting button monitoring...")
    poll_buttons()

if __name__ == "__main__":
    main()

