import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class CameraStreamBuffer:
    """
    A buffer for MJPEG stream processing.

    This class accumulates incoming bytes from the camera stream and provides a mechanism to flush the buffer
    when a complete frame is received. It is designed to work with picamera2's MJPEG stream.
    """

    def __init__(self, c: Picamera2.Picamera2):
        """
        Initializes the buffer with the picamera2 camera instance.

        Args:
            c: The picamera2.Picamera2 instance.
        """
        self.c = c
        self.b = io.BytesIO()
        self.frame_complete = False
        self.frame_type = None
        self.current_frame = None
        self.previous_frame = None
        self.callback = None

    def write(self, d: bytes) -> None:
        """
        Accumulates bytes from the camera stream into the buffer.

        Args:
            d: The bytes to accumulate.
        """
        try:
            self.b.write(d)
            self.flush()
        except Exception as e:
            logger.error(f"Error writing to buffer: {e}")

    def flush(self) -> None:
        """
        Flushes the buffer, decoding any accumulated JPEG frames.

        Raises:
            Exception: If there is an error during frame decoding.
        """
        try:
            if self.b.getbuffer() is None:
