class CameraStreamBuffer:
    """
    A buffer for MJPEG stream processing.

    This class accumulates incoming bytes from the camera stream and provides a mechanism to flush the buffer
    when a complete frame is received. It is designed to work with picamera2's MJPEG stream.
    """

    def __init__(self, c: Picamera2.Picamera2):
        """
