#!/usr/bin/env python3

import time
import signal
import sys
import os
import logging
import threading
import numpy as np
import cv2
import face_recognition
import pygame.mixer
import pygame.locals
import gpiozero
import config

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
door_lock = None
face_recognizer = None
camera = None
mixer = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    if door_lock:
        door_lock.release()
    if mixer:
        mixer.quit()
    if camera:
        camera.close()
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to initialize the door lock
def initialize_door_lock():
    global door_lock
    try:
        door_lock = gpiozero.DoorLock(18, 17, active_high=True)
        logging.info("Door lock initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize door lock: {e}")
        sys.exit(1)

# Function to initialize the camera
def initialize_camera():
    global camera
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            logging.error("Failed to open camera.")
            sys.exit(1)
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        sys.exit(1)

# Function to initialize the face recognizer
def initialize_face_recognizer():
    global face_recognizer
    try:
        face_recognizer = cv2.face.EigenFaceRecognizer_create()
        face_recognizer.read(config.TRAINING_FILE)
        logging.info("Face recognizer initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize face recognizer: {e}")
        sys.exit(1)

# Function to capture frames from the camera
def capture_frames():
    global camera
    try:
        ret, frame = camera.read()
        if not ret:
            logging.error("Failed to capture frame.")
