import argparse
import time
import signal
import sys
import os
import threading
import RPi.GPIO as GPIO
from gpiozero import LED
import smbus2
import psutil
import subprocess

# Constants
LCD_I2C_ADDR = 0x27
LED_GPIO_PINS = [17, 18, 23, 27, 22]  # BCM GPIO numbers
CLASS_TO_LED_MAP = {
    0: LED(LED_GPIO_PINS[0]),
    1: LED(LED_GPIO_PINS[1]),
    2: LED(LED_GPIO_PINS[2]),
    3: LED(LED_GPIO_PINS[3]),
    4: LED(LED_GPIO_PINS[4]),
}

# Global flag to signal the main thread to exit
running = True

# Function to handle SIGINT and SIGTERM signals
def signal_handler(sig, frame):
    global running
    print("Received signal, shutting down...")
    running = False
    GPIO.cleanup()  # Clean up GPIO pins on exit
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to initialize the LCD
def initialize_lcd():
    """Initializes the LCD and returns a threading.Event for signaling the main thread."""
    try:
        bus = smbus2.SMBus(1)  # Use I2C bus 1
        lcd = LCD_I2C_ADDR
        for i in range(16):
            for j in range(2):
                bus.write_byte_data(lcd, 0x80 + j * 2, 0x00)
                bus.write_byte_data(lcd, 0x80 + j * 2 + 1, 0x00)
        return True
    except Exception as e:
        print(f"LCD initialization failed: {e}")
        return False

# Function to update the LCD with CPU usage and temperature
def update_lcd(cpu_usage, cpu_temp):
    """Updates the LCD with CPU usage and CPU temperature."""
    try:
        lcd.clear()
        lcd.write_string("CPU Usage: {0} %\n".format(cpu_usage))
        lcd.write_string("CPU Temp: {0} C\n".format(cpu_temp))
    except Exception as e:
        print(f"LCD update failed: {e}")

# Function to run the YOLOv5 inference loop
def run_yolo_inference(model, image_path, output_path, classes, class_to_led):
    """Runs the YOLOv5 inference loop and updates the LCD."""
    try:
        # Load the model
        print("Loading model...")
        net = model.load_model(image_path)
        net.freeze()
        print("Inference started...")

        # Get the image
        print("Getting image...")
        image = cv2.imread(image_path)
        if image is None:
            raise FileNotFoundError(f"Image not found: {image_path}")

        # Run inference
        print("Running inference...")
        results = net.run(image)

        # Process the results
        print("Processing results...")
        for i, result in enumerate(results):
            if len(result) == 0:
                continue
            class_id = int(result[0][0][1])
            class_name = classes[class_id]
            class_color = class_to_led[class_id]
            if class_name in result[0][0][2]:
                print(f"Detected {class_name} at {result[0][0][2][class_name]}")
                class_color.on()
                time.sleep(0.5)
                class_color.off()
                print("Clearing LED...")
                class_color.off()
            else:
                print(f"No detection for {class_name}")

        # Write the results to the output file
        print("Writing results to output file...")
        with open(output_path, 'w') as f:
            for i, result in enumerate(results):
                if len(result) == 0:
                    continue
                class_id = int(result[0][0][1])
                class_name = classes[class_id]
                class_color = class_to_led[class_id]
                if class_name in result[0][0][2]:
                    f.write(f"{class_name}\n")
                else:
                    f.write("-1\n")

        print("Inference complete.")

    except Exception as e:
        print(f"Inference failed: {e}")

# Function to initialize the YOLOv5 model
def initialize_yolo():
    """Initializes the YOLOv5 model."""
    try:
        model = cv2.dnn.readNet("yolov5s.pt")
        net = model.get_network()
        net.setPreferableBackend(cv2.dnn.DNN_BACKEND_OPENCV)
        net.setPreferableTarget(cv2.dnn.DNN_TARGET_CPU)
        return net
    except Exception as e:
        print(f"YOLOv5 initialization failed: {e}")
        return None

# Function to load the YOLOv5 model
def load_yolo_model(model_path):
    """Loads the YOLOv5 model from the specified path."""
    try:
        net = cv2.dnn.readNet(model_path)
        net.setPreferableBackend(cv2.dnn.DNN_BACKEND_OPENCV)
        net.setPreferableTarget(cv2.dnn.DNN_TARGET_CPU)
        return net
    except Exception as e:
        print(f"YOLOv5 model loading failed: {e}")
        return None

# Function to initialize the I2C bus
def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        bus = smbus2.SMBus(1)
        return bus
    except Exception as e:
        print(f"I2C bus initialization failed: {e}")
        return None

# Function to initialize the LCD
def initialize_lcd():
    """Initializes the LCD and returns a threading.Event for signaling the main thread."""
    try:
        bus = initialize_i2c()
        if bus is None:
            return False

        lcd = initialize_lcd_thread(bus)
        if lcd is None:
            return False
        return True
    except Exception as e:
        print(f"LCD initialization failed: {e}")
        return False

# Function to initialize the LCD thread
def initialize_lcd_thread(bus):
    """Initializes the LCD thread."""
    lcd_thread = threading.Thread(target=lcd_update, args=(bus,))
    lcd_thread.daemon = True
    lcd_thread.start()
    return lcd_thread

# Function to update the LCD thread
def lcd_update(bus):
    """Updates the LCD thread."""
    while running:
        try:
            cpu_usage = psutil.cpu_percent()
            cpu_temp = os.popen("vcgencmd measure_temp").readline().rstrip()
