import serial
import time
import signal
import sys

# Constants for serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
PARITY = serial.PARITY_NONE
STOPBITS = serial.STOPBITS_ONE
TIMEOUT = 1

# Global variable to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C signal to stop the program gracefully."""
    global running
    print("Exiting program...")
    running = False

def read_weather_data(serial_port):
    """Reads weather data from the serial port and validates it."""
    try:
        with serial_port as ser:
            while running:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line:
                    try:
                        temperature, humidity, pressure = line.split(',')
                        if temperature.isdigit() and -40 <= int(temperature) <= 85:
                            print(f"Temperature: {temperature} °C, Humidity: {humidity} %, Pressure: {pressure} hPa")
                        else:
                            print(f"Warning: Invalid temperature reading: {temperature}")
                            continue
                        if 0 <= int(humidity) <= 100:
                            print(f"Humidity: {humidity} %, Pressure: {pressure} hPa")
                        else:
                            print(f"Warning: Invalid humidity reading: {humidity}")
                            continue
                        if 800 <= int(pressure) <= 1200:
                            print(f"Pressure: {pressure} hPa")
                        else:
                            print(f"Warning: Invalid pressure reading: {pressure}")
                    except ValueError:
                        print(f"Warning: Invalid data format in line: {line}")
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to initialize serial port and start the data reading loop."""
    global running
    running = True

    # Register the signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, parity=PARITY, stopbits=STOPBITS, timeout=TIMEOUT) as ser:
            print(f"Connected to weather sensor on {SERIAL_PORT} at {BAUD_RATE} baud.")
            read_weather_data(ser)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

