import time
import sys
from gpiozero import CPUTemperature

# Define a function to read and print the CPU temperature
def read_cpu_temperature():
    """Reads and prints the CPU temperature."""
    try:
        cpu_temp = CPUTemperature()
        print(f"CPU Temperature: {cpu_temp.C:.2f} °C")
    except FileNotFoundError:
        print("Error: Thermal sensor file not found. Please check the sensor connection.")
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")

# Main execution block
if __name__ == "__main__":
    try:
        # Start the temperature reading loop
        while True:
            read_cpu_temperature()
            time.sleep(5)  # Wait 5 seconds before the next reading
    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("\nProgram terminated")
    except Exception as e:
        # Handle any other unexpected errors
        print(f"An error occurred: {e}")
    finally:
        # Ensure the program exits cleanly
        sys.exit(0)

