import serial
import time
import csv
import os

# Configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1

# Initialize serial port
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    exit(1)

# Function to read temperature from serial port
def read_temperature():
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                celsius = float(line)
                return celsius
            except ValueError:
                print(f"Error: Invalid temperature reading: {line}")
                return None
        else:
            print("No temperature data received.")
            return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

# Function to convert Celsius to Fahrenheit
def convert_to_fahrenheit(celsius):
    return (celsius * 9/5) + 32

# Function to write data to CSV file
def write_to_csv(timestamp, celsius, fahrenheit):
    try:
        with open('temperature_log.csv', 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, celsius, fahrenheit])
    except FileNotFoundError:
        print("CSV file not found. Creating a new one.")
        os.makedirs('temperature_log', exist_ok=True)  # Create directory if it doesn't exist
        with open('temperature_log/temperature_log.csv', 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['timestamp', 'celsius', 'fahrenheit'])
    except Exception as e:
        print(f"Error writing to CSV file: {e}")

# Main function
def main():
    try:
        while True:
            temperature = read_temperature()
            if temperature is not None:
                fahrenheit = convert_to_fahrenheit(temperature)
                write_to_csv(time.strftime('%Y-%m-%d %H:%M:%S'), temperature, fahrenheit)
            else:
                print("Failed to read temperature.")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

