import time
import json
import requests
from adafruit_dht import DHT11

# Configuration
DHT_PIN = 4  # GPIO pin connected to the DHT11 data pin
SERVER_URL = "http://127.0.0.1:5000/data"  # URL for the Flask server
READ_INTERVAL_SECONDS = 5

def read_dht11_sensor():
    """Reads temperature and humidity from the DHT11 sensor."""
    try:
        sensor = DHT11(DHT_PIN)
        sensor.measure()
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor: {e}")
        return None, None

def send_data_to_server(temperature, humidity):
    """Sends temperature and humidity data to the Flask server."""
    data = {"temperature": temperature, "humidity": humidity}
    try:
        response = requests.post(SERVER_URL, json=data)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Server response: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Server error: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = read_dht11_sensor()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data_to_server(temperature, humidity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

