import serial
import time

# Configure serial port for the sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def read_sensor_data(serial_connection):
    """Reads temperature and humidity from the sensor and returns the values."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = line.split(',')
            temperature = float(temperature)
            humidity = float(humidity)
            return temperature, humidity
        else:
            return None, None
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None, None
    except ValueError as e:
        print(f"Invalid data format: {e}")
        return None, None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None, None

def process_data(temperature, humidity):
    """Processes the sensor data and prints the readings."""
    if temperature is not None and humidity is not None:
        print(f'Temperature: {temperature:.1f}°C')
        print(f'Humidity: {humidity:.1f}%')
        if temperature > 30.0:
            print('ALERT: High temperature!')
        if humidity > 70.0:
            print('ALERT: High humidity!')

def main():
    """Main function to read sensor data and process it."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            while True:
                temperature, humidity = read_sensor_data(ser)
                if temperature is not None and humidity is not None:
                    process_data(temperature, humidity)
                time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

