#!/usr/bin/env python3

import time
import signal
import sys
import subprocess
import logging
import os
from functools import partial
from gpiozero import PWMOutputDevice

# Configuration
FAN_PIN = 14  # BCM pin for the fan
PWM_FREQUENCY = 100  # Hz
DEGRADED_MODE = False  # Set to True for degraded mode

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global variables
fan = None
last_speed = 0

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logger.info("Shutting down gracefully...")
    if fan:
        fan.stop()
    sys.exit(0)

def get_cpu_temperature():
    """Reads the CPU temperature from the system."""
    try:
        output = subprocess.check_output(['vcgencmd', 'measure_temp'], text=True).strip()
        temperature = float(output.split('=')[1].split('\'')[0])
        return temperature
    except (subprocess.CalledProcessError, IndexError, ValueError) as e:
        logger.error(f"Error reading temperature: {e}")
        return None

def set_fan_speed(speed):
    """Sets the fan speed using PWM."""
    global fan
    if fan:
        fan.duty_cycle = speed
        logger.info(f"Fan speed set to {speed}%")
    else:
        logger.warning("Fan not initialized. Cannot set speed.")

def calculate_fan_speed(temperature):
    """Calculates the fan speed based on the temperature."""
    global last_speed
    if temperature is None:
        return last_speed  # Use last known speed if temperature is unavailable

    if temperature > 70:
        speed = 100
    elif temperature > 60:
        speed = 85
    elif temperature > 50:
        speed = 70
    elif temperature > 40:
        speed = 50
    elif temperature > 32:
        speed = 25
    elif temperature > 25:
        speed = 15
    else:
        speed = 0

    if speed != last_speed:
        logger.info(f"Temperature: {temperature:.1f}°C, Fan speed: {speed}%")
        last_speed = speed
    return speed

def main():
    """Main function to control the fan."""
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY)
        if DEGRADED_MODE:
            logger.info("Running in degraded mode.")
            set_fan_speed(0)  # Set initial speed to 0%
        else:
            set_fan_speed(100) # Initial speed is 100%

        while True:
            temperature = get_cpu_temperature()
            if temperature is not None:
                speed = calculate_fan_speed(temperature)
                set_fan_speed(speed)
            time.sleep(5)
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        if fan:
            fan.stop()
        sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

