import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Temperature and humidity thresholds
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def read_sensor_data(serial_port):
    """Reads temperature and humidity data from the serial sensor."""
    try:
        with serial.Serial(serial_port, BAUD_RATE, timeout=TIMEOUT) as ser:
            while True:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line:
                    try:
                        temperature, humidity = line.split(',')
                        temperature = float(temperature)
                        humidity = float(humidity)
                        print(f'Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%')
                        if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                            print('Alert: Temperature or humidity exceeds threshold!')
                    except ValueError:
                        print(f"Invalid data format: {line}")
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to initialize and run the sensor reading loop."""
    try:
        # Initialize serial communication
        sensor = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Serial port {SERIAL_PORT} initialized.")

        # Start the sensor reading loop
        while True:
            read_sensor_data(sensor)
            time.sleep(1)

    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial port is closed on exit
        if 'sensor' in locals() and sensor.is_open:
            sensor.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

