#!/usr/bin/env python3

"""
This script controls the servo motor connected to the Raspberry Pi GPIO pins.
It simulates a bird feeder system for a smart home demonstration.
"""

import time
import random
from gpiozero import OutputDevice, DigitalOutputDevice

# Define GPIO pins connected to the servo motor
SERVO_PINS = [14, 18, 20, 21]

# Define the number of pulse durations to simulate the servo movement
PULSE_DURATIONS = 1600

# Define the number of times to repeat the pulse train
REPEAT_COUNT = PULSE_DURATIONS * 2

# Define the minimum and maximum pulse durations for the servo
MIN_PULSE_DURATION = 156.25  # Microseconds
MAX_PULSE_DURATION = 312.5  # Microseconds

def initialize_gpio():
    """Initializes the GPIO pins for the servo motor."""
    try:
        # Create OutputDevice instances for each servo pin
        servo_pins = [OutputDevice(pin) for pin in SERVO_PINS]
        return servo_pins
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None

def set_servo_pin(pin, position):
    """Sets the position of a servo motor pin."""
    try:
        pin.value = position
    except Exception as e:
        print(f"Error setting servo pin {pin}: {e}")

def pulse_servo(pin, duration):
    """Pulses the servo pin for a specified duration."""
    try:
        # Set the pin to HIGH to activate the servo
        pin.value = True
        time.sleep(duration)
        # Set the pin to LOW to deactivate the servo
        pin.value = False
        time.sleep(duration)
    except Exception as e:
        print(f"Error pulse-servo: {e}")

def simulate_servo_movement(servo_pins, min_pulse, max_pulse, repeat_count):
    """Simulates the movement of a servo motor."""
    try:
        for _ in range(repeat_count):
            for pin in servo_pins:
                set_servo_pin(pin, random.randint(min_pulse, max_pulse))
            pulse_servo(servo_pins[0], random.randint(min_pulse, max_pulse))
            time.sleep(0.1)
    except Exception as e:
        print(f"Error during servo movement: {e}")

def main():
    """Main function to control the servo motor."""
    servo_pins = initialize_gpio()
    if servo_pins is None:
        return

    try:
        # Set initial positions for the servo pins
        for pin in servo_pins:
            set_servo_pin(pin, random.randint(0, 180))

        # Simulate the servo movement
        simulate_servo_movement(servo_pins, MIN_PULSE_DURATION, MAX_PULSE_DURATION, REPEAT_COUNT)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO pins on exit
        for pin in servo_pins:
            pin.close()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

