import logging
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from serial import Serial

# Constants
DEFAULT_PORT = 9099
DEFAULT_TIMEOUT = 2
DEFAULT_GPS_MODULE = "Adafruit_GPS"

# Global variables
running = True
gps_serial = None
gps_i2c = None

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Shutting down gracefully...")
    running = False
    if gps_serial:
        gps_serial.close()
    if gps_i2c:
        gps_i2c.close()
    sys.exit(0)

# Signal handler for Ctrl+C
def signal_handler_exit(sig, frame):
    global running
    logging.info("Exiting...")
    running = False
    if gps_serial:
        gps_serial.close()
    if gps_i2c:
        gps_i2c.close()
    sys.exit(0)

# Function to handle GPS module initialization
def initialize_gps(module):
    global gps_serial, gps_i2c
    try:
        if module == "Adafruit_GPS":
            gps_serial = Serial(port=DEFAULT_PORT, baudrate=9600, timeout=DEFAULT_TIMEOUT)
            gps_i2c = None
        elif module == "smbus2":
            gps_i2c = smbus2.SMBus(1)
        else:
            raise ValueError(f"Invalid GPS module: {module}")
        logging.info(f"GPS module initialized: {module}")
    except Exception as e:
        logging.error(f"Failed to initialize GPS module: {e}")
        raise

# Function to read GPS coordinates from the module
def read_gps_position():
    global gps_serial, gps_i2c
    try:
        if gps_serial:
            data = gps_serial.readline().decode('utf-8').strip()
            if data:
                try:
                    position = json.loads(data)
                    lat = position.get('lat')
                    lon = position.get('lon')
                    if lat and lon:
                        return lat, lon
                    else:
                        logging.warning("Invalid GPS data received.")
                        return None, None
                except json.JSONDecodeError:
                    logging.warning("Invalid GPS data format.")
                    return None, None
            else:
                logging.warning("No GPS data received.")
                return None, None
        elif gps_i2c:
            data = gps_i2c.readfrom_mem(0x01, 0x00, 8)
            if data:
                try:
                    position = json.loads(data.decode('utf-8').strip())
                    lat = position.get('lat')
                    lon = position.get('lon')
                    if lat and lon:
                        return lat, lon
                    else:
                        logging.warning("Invalid GPS data received.")
                        return None, None
                except json.JSONDecodeError:
                    logging.warning("Invalid GPS data format.")
                    return None, None
            else:
                logging.warning("No GPS data received.")
                return None, None
        else:
            logging.warning("No GPS module available.")
            return None, None
    except Exception as e:
        logging.error(f"Failed to read GPS coordinates: {e}")
        return None, None

# Function to handle remote control commands
def handle_command(command):
    global running
    try:
        if command == 'start':
            logging.info("Starting tracking...")
            running = True
        elif command == 'stop':
            logging.info("Stopping tracking...")
            running = False
        elif command == 'report':
            if running:
                lat, lon = read_gps_position()
                if lat and lon:
                    data = json.dumps({'lat': lat, 'lon': lon}).encode('utf-8')
                    logging.info(f"Reporting GPS coordinates: {data.decode('utf-8')}")
                else:
                    logging.warning("No GPS coordinates available.")
            else:
                logging.warning("Tracking is not running.")
        else:
            logging.warning(f"Invalid command: {command}")
    except Exception as e:
        logging.error(f"Error handling command: {e}")

# Function to listen for incoming connections
def listen_for_connections(port):
    global running
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.bind(('127.0.0.1', port))
        server_socket.listen(1)
        logging.info(f"Listening for connections on port {port}")
        while running:
            client_socket, client_address = server_socket.accept()
            logging.info(f"Accepted connection from {client_address}")
            threading.Thread(target=handle_command, args=(client_socket,)).start()
    except socket.error as e:
        logging.error(f"Socket error: {e}")
    except Exception as e:
        logging.error(f"Error listening for connections: {e}")

# Main function
def main():
    global running
    try:
        initialize_gps(DEFAULT_GPS_MODULE)
        listen_for_connections(DEFAULT_PORT)
    except Exception as e:
        logging.error(f"Initialization error: {e}")
    finally:
        if gps_serial:
            gps_serial.close()
        if gps_i2c:
            gps_i2c.close()
        logging.info("Exiting program.")

if __name__ == "__main__":
    main()

