import RPi.GPIO as GPIO
import time
import logging
from gpiozero import OutputDevice
from schedule import every, at

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin for the vibration motor
VIBRATION_PIN = 17

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(VIBRATION_PIN, GPIO.OUT)
    motor = OutputDevice(VIBRATION_PIN, active_high=False) # Use active low for vibration motor
except Exception as e:
    logging.error(f"GPIO initialization error: {e}")
    exit(1)  # Exit if GPIO initialization fails


def activate_vibration(duration: int = 30) -> None:
    """Activates the vibration motor for a specified duration."""
    try:
        logging.info("Activating vibration motor...")
        motor.on()
        time.sleep(duration)
        logging.info("Vibration motor deactivated.")
    except Exception as e:
        logging.error(f"Error activating vibration motor: {e}")


def deactivate_vibration() -> None:
    """Deactivates the vibration motor."""
    try:
        logging.info("Deactivating vibration motor...")
        motor.off()
    except Exception as e:
        logging.error(f"Error deactivating vibration motor: {e}")


def run_vibration_cycle(cycle_duration: int = 24, cycle_start_time: int = 21, cycle_end_time: int = 21) -> None:
    """Runs a vibration cycle for a specified duration and time."""
    try:
        logging.info(f"Running vibration cycle from {cycle_start_time} to {cycle_end_time} (24-hour cycle)")
        while True:
            activate_vibration(cycle_duration)
            time.sleep(cycle_end_time - cycle_start_time)
            deactivate_vibration()
            time.sleep(cycle_start_time - cycle_end_time + cycle_end_time - cycle_start_time) # Adjust sleep time to match cycle duration
    except KeyboardInterrupt:
