    except Exception as e:
        logging.error(f"Error during vibration cycle: {e}")


def main() -> None:
    """Main function to run the vibration cycle."""
    try:
        run_vibration_cycle()
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

