from http.server import BaseHTTPRequestHandler, HTTPServer
from gpiozero import OutputDevice
import RPi.GPIO as GPIO
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin for the relay
RELAY_PIN = 23

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(RELAY_PIN, GPIO.OUT)

# Initialize output device
relay = OutputDevice(RELAY_PIN)

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    GPIO.cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to handle the POST request
def handle_request(request):
    try:
        if request.method == 'POST':
            data = request.get_json()
            if data and 'state' in data:
                state = data['state']
                if state == 'on':
                    relay.on()
                    response = {'status': 'Relay state changed'}
                elif state == 'off':
                    relay.off()
                    response = {'status': 'Relay state changed'}
                else:
                    response = {'error': 'Invalid state value'}
            else:
                response = {'error': 'Invalid request format'}
        else:
            response = {'error': 'Invalid request method'}
        return response
    except Exception as e:
        logging.error(f"Error handling request: {e}")
        return {'error': f'An unexpected error occurred: {e}'}

# Function to start the Flask app
def start_flask_app():
    app = HTTPServer(('', 5000), BaseHTTPRequestHandler)
    app.handle_request = handle_request
    return app

# Main function
def main():
    try:
        app = start_flask_app()
        logging.info("Flask app started on port 5000")
        logging.info("Waiting for requests...")
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down gracefully...")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")
        logging.info("Flask app stopped.")

if __name__ == "__main__":
    main()

