import serial
import time

# Define the serial port and baud rate
SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_TIMEOUT = 1

def read_gps_data(serial_port):
    """Reads GPS data from the serial port and returns latitude and longitude."""
    try:
        with serial.Serial(serial_port, BAUD_RATE, timeout=READ_TIMEOUT) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        if line.startswith('$GPRMC'):
                            data = line.split(',')
                            if data[2] == 'A':  # Check if the fix is valid
                                latitude = data[3]
                                longitude = data[4]
                                return latitude, longitude
                except serial.SerialException as e:
                    print(f"Serial port error: {e}")
                    break
                except Exception as e:
                    print(f"Error processing data: {e}")
                    break
                time.sleep(1)  # Wait before reading again
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    return None, None

def convert_to_decimal_degrees(latitude, longitude):
    """Converts latitude and longitude from degrees, minutes, and decimal minutes to decimal degrees."""
    degrees, minutes, decimal_minutes = latitude.split('.')
    decimal_degrees = (degrees + minutes / 60 + decimal_minutes / 3600)
    return decimal_degrees

def main():
    """Main function to read and display GPS coordinates."""
    latitude, longitude = read_gps_data(SERIAL_PORT)

    if latitude and longitude:
        decimal_degrees = convert_to_decimal_degrees(latitude, longitude)
        print(f"Latitude: {decimal_degrees:.6f}")
        print(f"Longitude: {decimal_degrees:.6f}")
    else:
        print("Failed to retrieve GPS data.")

if __name__ == "__main__":
    main()

