import serial
import time
import os

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path
LOG_FILE = 'water_flow_log.txt'

# Initialize serial communication
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    print(f"Serial port {SERIAL_PORT} opened successfully.")
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    exit(1)

# Function to read and process flow rate data
def read_flow_rate():
    """Reads a line from the serial port, converts it to a float, and prints it."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                flow_rate = float(line)
                print(f"Flow rate: {flow_rate} L/min")
                log_flow_rate(flow_rate)
            except ValueError:
                print(f"Invalid data received: {line}")
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")

# Function to log flow rate data to a file
def log_flow_rate(flow_rate):
    """Appends the flow rate to the log file."""
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Flow Rate: {flow_rate} L/min\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

# Main loop
try:
    while True:
        read_flow_rate()
        time.sleep(1)
except KeyboardInterrupt:
    print("Program terminated by user.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")
finally:
    # Ensure serial port is closed on exit
    if serial_connection.is_open:
        serial_connection.close()
        print("Serial port closed.")
    print("Program finished.")

