import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define serial port and baud rate
SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1

# Define log file
LOG_FILE = 'power_consumption.log'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {port}: {e}")
        return None

def read_power_data(serial_port):
    """Reads power data from the serial port and logs it."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                power_value = float(line)
                logging.info(f'Power consumption: {power_value} W')
            except ValueError:
                logging.warning(f'Invalid data received: {line}')
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

def main():
    """Main function to initialize serial and read power data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        return

    try:
        while True:
            read_power_data(serial_connection)
            time.sleep(1)  # Read every second
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

