import serial
import time

# Define the serial port and baud rate for the Bluetooth device
BLUETOOTH_PORT = '/dev/rfcomm4'
BLUETOOTH_BAUD_RATE = 38400

# Function to establish a serial connection to the Bluetooth device
def connect_bluetooth(port, baud_rate):
    """Establishes a serial connection to the Bluetooth device."""
    try:
        bluetooth_serial = serial.Serial(port, baud_rate, timeout=1)
        return bluetooth_serial
    except serial.SerialException as e:
        raise RuntimeError(f"Error opening serial port: {e}")

# Function to send a command to the Bluetooth device
def send_command(bluetooth_serial, command):
    """Sends a command to the Bluetooth device."""
    try:
        bluetooth_serial.write(f'X{command}\n'.encode())
        time.sleep(0.1)  # Add a small delay to prevent flooding
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")

# Main function to interact with the Bluetooth device
def main():
    """Main function to establish a serial connection and send commands."""
    try:
        bluetooth_serial = connect_bluetooth(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)
        print("Connected to Bluetooth device. Type 'exit' to quit.")

        while True:
            try:
                command = input("Enter command (or 'exit'): ").strip().upper()
                if command == 'EXIT':
                    break
                send_command(bluetooth_serial, command)
            except KeyboardInterrupt:
                print("\nExiting program.")
                break
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        if 'bluetooth_serial' in locals() and bluetooth_serial.is_open:
            bluetooth_serial.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()

